import collections
import json
import os
def task_func(directory_path: str) -> dict:
    """
    Count the total appearances of all keys in all JSON files in the specified directory.
    This includes keys at all levels of nesting within the JSON objects.

    Args:
        directory_path (str): The path to the directory containing JSON files.

    Returns:
        dict: A dictionary with the keys from the JSON files as keys and their counts as values.
    """
    key_counts = collections.Counter()

    def extract_keys(data):
        """Recursively extract keys from a JSON-like structure (dict or list)."""
        if isinstance(data, dict):
            for key, value in data.items():
                key_counts[key] += 1
                extract_keys(value)
        elif isinstance(data, list):
            for item in data:
                extract_keys(item)

    # Check if the directory exists
    if not os.path.isdir(directory_path):
        return {}

    # Iterate through all files in the directory
    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    extract_keys(data)
            except (json.JSONDecodeError, IOError, UnicodeDecodeError):
                # Skip files that cannot be read or parsed as JSON
                continue

    return dict(key_counts)

