import numpy as np
from collections import defaultdict
import json
import csv
def task_func(input_file, output_file):
    """
    Reads a list of dictionaries from a JSON file, calculates the mean and median 
    for each numeric field, writes the results to a CSV file, and returns the 
    statistics as a dictionary.

    Args:
        input_file (str): Path to the input JSON file containing a list of dictionaries.
        output_file (str): Path to the output CSV file.

    Returns:
        dict: A dictionary where each key is a field from the input JSON and each 
              value is another dictionary with the 'mean' and 'median' of that field.
    """
    # Read the JSON file
    try:
        with open(input_file, 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

    if not isinstance(data, list):
        return {}

    # Group numeric values by key
    values_by_key = defaultdict(list)
    for entry in data:
        if not isinstance(entry, dict):
            continue
        for key, value in entry.items():
            # Check if the value is numeric (int or float) and not a boolean
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                values_by_key[key].append(value)

    # Calculate mean and median for each key
    results = {}
    for key, values in values_by_key.items():
        if values:
            results[key] = {
                'mean': float(np.mean(values)),
                'median': float(np.median(values))
            }

    # Write the results to a CSV file
    with open(output_file, 'w', newline='') as f:
        writer = csv.writer(f)
        # Write header
        writer.writerow(['Field', 'Mean', 'Median'])
        # Write data rows
        for key in sorted(results.keys()):
            stats = results[key]
            writer.writerow([key, stats['mean'], stats['median']])

    return results

